import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import menuItemService from '../../../services/menuItemService';
import { useAuth } from '../../hooks/useAuth';

const MenuItemList = ({ restaurantId }) => {
  const [menuItems, setMenuItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { token } = useAuth();

  useEffect(() => {
    const fetchMenuItems = async () => {
      setLoading(true);
      setError('');
      try {
        const items = await menuItemService.getMenuItemsByOwner(token);
        setMenuItems(items);
      } catch (err) {
        setError(err.message || 'Failed to fetch menu items.');
      } finally {
        setLoading(false);
      }
    };

    fetchMenuItems();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  const handleDelete = async (itemId) => {
    if (window.confirm('Are you sure you want to delete this menu item?')) {
      try {
        await menuItemService.deleteMenuItem(itemId, { restaurantId }, token); // Need to send restaurantId for backend validation
        setMenuItems(menuItems.filter(item => item._id !== itemId));
        console.log('Menu item deleted successfully.');
      } catch (err) {
        setError(err.message || 'Failed to delete menu item.');
      }
    }
  };

  if (loading) {
    return <div>Loading menu items...</div>;
  }

  if (error) {
    return <div style={{ color: 'red' }}>{error}</div>;
  }

  if (menuItems.length === 0) {
    return <p>No menu items added yet.</p>;
  }

  return (
    <div>
      <h4>Your Menu Items</h4>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <ul>
        {menuItems.map(item => (
          <li key={item._id}>
            {item.name} - ${item.price} ({item.isAvailable ? 'Available' : 'Unavailable'})
            <Link to={`/restaurant/menu/edit/${item._id}`}>Edit</Link>
            <button onClick={() => handleDelete(item._id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default MenuItemList;
